INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (1, 'Rajarshi Chhatrapati Shahu Maharaj Shikshan Shulkh Shishyavrutti Yojna (EBC)', 'Post-matric tuition and exam fee reimbursement scheme for economically backward class (EBC) students pursuing higher and technical education in Maharashtra.', 'STATE', 'Maharashtra', 'EDUCATION', '50% of Tuition Fee and Exam Fee reimbursement for general open category with income up to ₹8 Lakhs.', 'https://mahadbt.maharashtra.gov.in/', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (2, 'Dr. Punjabrao Deshmukh Vastigruh Nirvah Bhatta Yojna', 'Hostel maintenance allowance for children of registered small/marginal farmers and registered construction workers pursuing higher professional education away from home.', 'STATE', 'Maharashtra', 'EDUCATION', '₹30,000 per year for students studying in MMRDA/Pune/Nagpur; ₹20,000 per year for other district locations.', 'https://mahadbt.maharashtra.gov.in', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (3, 'Pradhan Mantri Kisan Samman Nidhi (PM-KISAN)', 'Direct income support of ₹6,000 per year in three equal installments to all landholding farmer families across India.', 'CENTRAL', 'All India', 'AGRICULTURE', '₹6,000 per year transferred directly to bank account in 3 equal four-monthly installments of ₹2,000.', 'https://pmkisan.gov.in', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (4, 'Namo Shetkari Mahasanman Nidhi Yojana (Maharashtra)', 'State supplement of ₹6,000 per year provided by Government of Maharashtra to all PM-Kisan registered farmers in the state, bringing total support to ₹12,000/year.', 'STATE', 'Maharashtra', 'AGRICULTURE', 'Additional ₹6,000 per year directly to bank account, combined with PM-KISAN for total ₹12,000/year.', 'https://krishi.maharashtra.gov.in', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (5, 'Pradhan Mantri Mudra Yojana (PMMY)', 'Collateral-free institutional micro-credit up to ₹10 Lakhs for non-corporate, non-farm small/micro enterprises across Shishu, Kishore, and Tarun loan tiers.', 'CENTRAL', 'All India', 'BUSINESS', 'Collateral-free loans: Shishu (up to ₹50,000), Kishore (₹50,000 to ₹5 Lakh), Tarun (₹5 Lakh to ₹10 Lakh).', 'https://www.mudra.org.in', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (6, 'Chief Minister Employment Generation Programme (CMEGP - Maharashtra)', 'Credit-linked subsidy program to generate self-employment ventures in manufacturing and service sectors in Maharashtra with subsidies up to 35%.', 'STATE', 'Maharashtra', 'BUSINESS', 'Financial assistance up to ₹50 Lakh (Manufacturing) and ₹20 Lakh (Service) with 15% to 35% government capital subsidy.', 'https://maha-cmegp.gov.in', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (7, 'Pradhan Mantri Awas Yojana - Urban (PMAY-U)', 'Affordable housing mission providing credit-linked interest subsidy and financial assistance for pucca house construction or purchase to eligible urban families.', 'CENTRAL', 'All India', 'SOCIAL_SUPPORT', 'Direct central assistance of ₹1.5 Lakh to ₹2.67 Lakh through upfront interest subsidy or direct beneficiary-led construction grant.', 'https://pmaymis.gov.in', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (8, 'Ayushman Bharat - Pradhan Mantri Jan Arogya Yojana (PM-JAY)', 'World''s largest government-funded healthcare assurance scheme offering health cover of ₹5 Lakhs per family per year for secondary and tertiary care hospitalization.', 'CENTRAL', 'All India', 'HEALTHCARE', 'Cashless and paperless hospitalization coverage of up to ₹5,00,000 per family per year across 27,000+ empanelled hospitals.', 'https://nha.gov.in/PM-JAY', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (9, 'PM Vishwakarma Scheme', 'Comprehensive central support for traditional artisans and craftspeople across 18 trades, providing recognition, skill upgrades, toolkits, and subsidized collateral-free loans.', 'CENTRAL', 'All India', 'BUSINESS', 'PM Vishwakarma Certificate & ID, ₹15,000 toolkit incentive, skill training with ₹500/day stipend, and collateral-free enterprise loans up to ₹3 Lakh at 5% interest.', 'https://pmvishwakarma.gov.in', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (10, 'Startup India Seed Fund Scheme (SISFS)', 'Financial assistance to early-stage innovative startups for proof of concept, prototype development, product trials, market entry, and commercialization.', 'CENTRAL', 'All India', 'BUSINESS', 'Up to ₹20 Lakhs as grant for validation of proof of concept / prototype, and up to ₹50 Lakhs through convertible debentures or debt.', 'https://seedfund.startupindia.gov.in', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (11, 'Post Matric Scholarship for SC / ST Students (Maharashtra Social Justice)', '100% tuition and examination fee waiver, maintenance allowance, and library support for SC and ST students enrolled in post-SSC approved courses.', 'STATE', 'Maharashtra', 'EDUCATION', '100% Tuition & Exam fee exemption directly credited to college; monthly maintenance allowance credited to student''s bank account.', 'https://mahadbt.maharashtra.gov.in', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (12, 'Pradhan Mantri Fasal Bima Yojana (PMFBY)', 'Comprehensive multi-peril crop insurance covering yield loss and post-harvest damages from non-preventable natural risks at a nominal farmer premium of 1.5% to 2%.', 'CENTRAL', 'All India', 'AGRICULTURE', 'Full sum insured payout against crop failure due to drought, unseasonal rain, pests, hail, and localized perils. Farmers pay only ₹1 token premium in Maharashtra.', 'https://pmfby.gov.in', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (13, 'PM SVANidhi — PM Street Vendor''s AtmaNirbhar Nidhi', 'Micro-credit scheme providing affordable collateral-free working capital loans to street vendors helping them resume livelihoods and build credit history.', 'CENTRAL', 'All India', 'BUSINESS', 'Collateral-free loans: ₹10,000 (Level 1), ₹20,000 (Level 2), ₹50,000 (Level 3) on timely repayment. Cashback reward on digital transactions.', 'https://pmsvanidhi.mohua.gov.in', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (14, 'Stand-Up India Scheme', 'Facilitates bank loans of ₹10 Lakh to ₹1 Crore to SC/ST borrowers and women entrepreneurs for setting up greenfield manufacturing or service enterprises.', 'CENTRAL', 'All India', 'BUSINESS', 'Composite loan of ₹10 Lakh to ₹1 Crore (75% of project cost) with 7-year repayment.', 'https://www.standupmitra.in', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (15, 'Sukanya Samriddhi Yojana (SSY)', 'Small savings scheme for girl children below 10 years offering the highest guaranteed interest rate (8.2% p.a.) with full EEE tax exemption.', 'CENTRAL', 'All India', 'WELFARE', '8.2% guaranteed annual interest; full EEE tax exemption; partial withdrawal at 18 for education; maturity at 21.', 'https://www.indiapost.gov.in/Financial/Pages/Content/SSY.aspx', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (16, 'Atal Pension Yojana (APY)', 'Guaranteed minimum pension scheme for unorganised sector workers ensuring social security in old age with government co-contribution.', 'CENTRAL', 'All India', 'WELFARE', 'Guaranteed monthly pension of ₹1,000 to ₹5,000 after age 60, based on contribution and entry age.', 'https://npscra.nsdl.co.in/scheme-details.php', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (17, 'Pradhan Mantri Jan Dhan Yojana (PMJDY)', 'National financial inclusion mission ensuring universal access to banking, savings, credit, insurance, and remittance for every household.', 'CENTRAL', 'All India', 'WELFARE', 'Zero-balance savings account, RuPay card with ₹2 Lakh accident insurance, ₹30,000 life cover, ₹10k overdraft after 6 months.', 'https://pmjdy.gov.in', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (18, 'National Scholarship Portal (NSP) — Central Schemes', 'One-stop platform providing Post-Matric, Pre-Matric, and Merit-cum-Means scholarships from multiple central ministries to SC, ST, OBC, Minority, and EWS students.', 'CENTRAL', 'All India', 'EDUCATION', '₹230 to ₹1,200/month maintenance + full tuition fees depending on institution and course.', 'https://nsp.gov.in/', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (19, 'Pradhan Mantri Ujjwala Yojana 2.0 (PMUY)', 'Free LPG connection scheme for women from BPL households enabling clean cooking fuel access and reducing indoor air pollution.', 'CENTRAL', 'All India', 'WELFARE', 'Free LPG deposit waiver, 1 free refill, stove and regulator on easy EMI.', 'https://pmuy.gov.in', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (20, 'Beti Bachao Beti Padhao (BBBP)', 'Multi-sectoral programme to prevent gender-biased sex selection and ensure survival, protection, and education of girl children across India.', 'CENTRAL', 'All India', 'WELFARE', 'Free girl child registration, conditional cash support for education and healthcare, linked with SSY, PCPNDT enforcement and school retention programs.', 'https://wcd.nic.in/schemes/beti-bachao-beti-padhao-scheme', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (21, 'Soil Health Card Scheme', 'Government scheme issuing Soil Health Cards to farmers every 2 years with crop-wise fertilizer recommendations based on soil testing to improve productivity.', 'CENTRAL', 'All India', 'AGRICULTURE', 'FREE soil testing (macro & micro nutrients), crop-wise fertilizer dosage recommendation, long-term productivity improvement.', 'https://soilhealth.dac.gov.in', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (22, 'eNAM — National Agriculture Market', 'Pan-India electronic trading portal integrating APMCs for online price discovery and seamless trade of agricultural commodities across 1000+ mandis.', 'CENTRAL', 'All India', 'AGRICULTURE', 'Access to 1000+ APMCs, real-time price discovery, reduced intermediary fees, direct payment to bank account, lower post-harvest losses.', 'https://enam.gov.in', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (23, 'Pradhan Mantri Garib Kalyan Anna Yojana (PMGKAY)', 'Free food grain distribution providing additional 5 kg wheat/rice per person per month free of cost to all NFSA ration card holders, extended through December 2028.', 'CENTRAL', 'All India', 'WELFARE', '5 kg wheat/rice FREE per person per month above regular NFSA entitlement. No cost to beneficiary.', 'https://dfpd.gov.in', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
INSERT INTO schemes (id, name, description, government_level, state, category, benefit, source_url, last_verified, active, is_demo_data, created_at, updated_at) VALUES (24, 'Maharashtra Ladki Bahin Yojana', 'State flagship DBT scheme providing monthly financial assistance to eligible women of Maharashtra aged 21-65 years to promote financial independence.', 'STATE', 'Maharashtra', 'WELFARE', '₹1,500 per month directly to Aadhaar-linked bank account (₹18,000 per year).', 'https://ladakibahin.maharashtra.gov.in', '2026-03-01', true, false, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), benefit=VALUES(benefit);
