INSERT INTO government_updates (title, description, category, source, source_url, published_date, active, created_at) VALUES ('MahaDBT Post-Matric Scholarship Portal Extended for AY 2025-26', 'Government of Maharashtra has extended the deadline for online submission of post-matric scholarship applications for SC, ST, VJNT, and Open EBC students until April 30, 2026.', 'EDUCATION', 'Directorate of Higher & Technical Education, Maharashtra', 'https://mahadbt.maharashtra.gov.in', '2026-03-15', true, NOW());
INSERT INTO government_updates (title, description, category, source, source_url, published_date, active, created_at) VALUES ('PM-KISAN 19th Installment Released via Direct Benefit Transfer', 'Prime Minister released the 19th installment of PM-KISAN, disbursing over ₹20,000 Crores directly into the Aadhaar-linked bank accounts of more than 9.5 crore landholding farmer families.', 'AGRICULTURE', 'Press Information Bureau (PIB), Ministry of Agriculture', 'https://pmkisan.gov.in', '2026-03-10', true, NOW());
INSERT INTO government_updates (title, description, category, source, source_url, published_date, active, created_at) VALUES ('Mandatory Aadhaar-NPCI Seeding for State & Central Welfare Subsidies', 'UIDAI and National Payments Corporation of India (NPCI) issue citizen advisory: ensure bank accounts are mapped to Aadhaar payment bridge to avoid DBT scholarship or farming grant transaction bounces.', 'SOCIAL_SUPPORT', 'Ministry of Electronics and Information Technology (MeitY)', 'https://myaadhaar.uidai.gov.in', '2026-03-05', true, NOW());
INSERT INTO government_updates (title, description, category, source, source_url, published_date, active, created_at) VALUES ('Maharashtra Revenue Department Introduces 24-Hour Instant Digital 7/12', 'Mahabhumi portal upgrades to high-speed cloud infrastructure allowing citizens to download digitally signed 7/12 and 8A extracts with instant QR verification code.', 'AGRICULTURE', 'Revenue & Forest Department, Maharashtra', 'https://digitalsatbara.mahabhumi.gov.in', '2026-03-01', true, NOW());
